import java.util.*;

public class Main {

    private static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

    static String readstring() {
        return read_string_from_buffer();
    }

    static int readint() {
        return read_int_from_buffer();
    }

    static String read_string_from_buffer() {
        try {
            String input_text = reader.readLine();
            if (input_text == null) {
                return "";
            }
            return input_text.trim();
        } catch (IOException e) {
            throw new RuntimeException("failed to read from stdin");
        }
    }

    static int read_int_from_buffer() {
        return Integer.parseInt(read_string_from_buffer());
    }

    static List<Integer> read_line_of_integers() {
        String[] parts = readstring().split("\\s+");
        List<Integer> res = new ArrayList<>();
        for (String x : parts) {
            if (!x.isEmpty()) {
                res.add(Integer.parseInt(x));
            }
        }
        return res;
    }

    static List<Long> read_line_of_longs() {
        String[] parts = readstring().split("\\s+");
        List<Long> res = new ArrayList<>();
        for (String x : parts) {
            if (!x.isEmpty()) {
                res.add(Long.parseLong(x));
            }
        }
        return res;
    }

    static int h(List<Integer> par, List<Integer> d, int i) {
        if (i == 1) {
            return -1;
        }
        int p = par.get(i - 2);
        if (d.get(i - 2) == 0) {
            d.set(i - 2, h(par, d, p) + 1);
        }
        return d.get(i - 2);
    }

    public static void main(String[] args) {
        List<Integer> v = read_line_of_integers();
        int a = Math.min(v.get(0), v.get(1));
        int b = Math.max(v.get(0), v.get(1));
        if (a + v.get(2) <= b) {
            System.out.println(2 * (a + v.get(2)));
        } else {
            System.out.println(2 * b + ((v.get(2) - (b - a)) / 2) * 2);
        }
    }
}

