        }
        return temp;
    }

    static int h(int[] par, int[] d, int i) {
        if (i == 1) {
            return -1;
        }
        int p = par[i - 2];
        if (d[i - 2] == 0) {
            d[i - 2] = h(par, d, p) + 1;
        }
        return d[i - 2];
    }

    public static void main(String[] args) throws Exception {
        int[] v = readLineOfIntegers();
        int a = Math.min(v[0], v[1]);
